 'kin-bts':ref('BTS · Bronquiectasias en adultos','https://bmjopenrespres.bmj.com/content/5/1/e000348',2018,'Guía clínica','Técnicas, tolerancia y posiciones para limpieza bronquial'),
 'kin-ers':ref('ERS 2025 · Bronquiectasias en adultos','https://publications.ersnet.org/content/erj/66/6/2501126',2025,'Guía GRADE','PICO 1: enseñanza de técnicas de limpieza bronquial'),
