 'kin-postcovid':ref('OMS · Rehabilitación en condición pos-COVID-19','https://www.who.int/teams/health-care-readiness/post-covid-19-condition',2023,'Recomendaciones oficiales','Rehabilitación y exacerbación de síntomas posesfuerzo (PESE)','Recomendaciones oficiales gratuitas'),
