 'kin-safety':ref('Hodgson et al. · Seguridad de movilización en UCI','https://pmc.ncbi.nlm.nih.gov/articles/PMC4301888/',2014,'Consenso experto','Dominios respiratorio, cardiovascular, neurológico y dispositivos'),
 'kin-padis':ref('SCCM PADIS · Actualización focalizada 2025','https://www.sccm.org/clinical-resources/guidelines/guidelines/focused-update-padis-guideline',2025,'Guía GRADE','Movilización y rehabilitación mejoradas: recomendación condicional','Recomendaciones oficiales gratuitas'),
