 'kin-suction':ref('AARC 2022 · Aspiración de la vía aérea artificial','https://www.aarc.org/wp-content/uploads/2022/10/cpg-artificial-airway-suctioning.pdf',2022,'Guía clínica y consenso','Indicaciones, preoxigenación, técnica y prevención de daño'),
 'kin-sbt':ref('AARC 2024 · Pruebas de respiración espontánea','https://pmc.ncbi.nlm.nih.gov/articles/PMC11285503/',2024,'Guía GRADE','Cuatro recomendaciones y distinción liberación/extubación')
