// Options are authored together, then their keys are distributed deterministically.
function question(id,source,skill,index,[prompt,correct,a,b,c,d,why]){
 const options=[correct,a,b,c,d],answer=index%5;
 options.unshift(...options.splice(options.length-answer,answer));
 return {id,source,skill,prompt,options,answer,why};
}
function lesson(course,n,title,refs,objective,body,trap,evidence,activity,rows){
 const id=`${course}-m${n}`;
 return {id,title,area:title,minutes:25,source:refs[0],references:refs,objective,body,trap,evidence,
  simulation:{required:false,scenario:activity.scenario,roles:['Kinesiólogo/a','Paciente simulado o responsable del pase','Observador/a'],rotation:'Rotar roles. Explicar la decisión y repetir el pase después de la devolución.',checklist:activity.checklist,validation:'Actividad de razonamiento con caso ficticio. Las maniobras y el manejo de equipos requieren entrenamiento presencial supervisado; este ejercicio no acredita destreza.'},
  questions:rows.map((row,i)=>question(`${id}-q${i+1}`,refs[0],title,(n-1)*4+i,row))};
}
const clinical='kine-clinica',resp='kine-respiratoria',icu='kine-uci',vent='kine-ventilacion';
const clinicalLessons=[
 lesson(clinical,1,'Evaluación funcional y objetivos compartidos',['kin-icf','kin-whodas'],'Transformar la entrevista en un problema funcional medible.',
  'Una evaluación kinésica comienza por lo que la persona necesita volver a hacer. El diagnóstico médico aporta contexto, pero no describe por sí solo la dificultad para levantarse, caminar o participar en la vida familiar. La CIF permite ordenar funciones y estructuras corporales, actividades, participación y factores ambientales. WHODAS ofrece una evaluación estandarizada de funcionamiento; no reemplaza el examen específico ni se debe modificar su puntuación de manera improvisada.\n\nEn la entrevista registrá motivo de consulta, evolución, tratamientos, comorbilidades, caídas, ayudas utilizadas, autonomía previa y expectativas. Pedí consentimiento para evaluar y acordá cómo comunicar dolor o necesidad de parar. Después elegí tareas observables y seguras: por ejemplo, pasar de una silla a otra con la ayuda habitual. Anotá condiciones, asistencia requerida y síntomas, además del resultado.\n\nEjemplo didáctico: Marta quiere volver a cocinar. «Mejorar fuerza» es insuficiente como objetivo compartido. Una meta puede ser permanecer de pie el tiempo necesario para preparar una merienda, con descansos acordados y sin perder estabilidad. El plazo y la dosis se negocian después de medir la situación inicial. En la reevaluación usá las mismas condiciones y preguntá si el cambio se trasladó a su actividad real. Una puntuación mejor sin mayor participación también merece explicación.',
  'Confundir una mejoría de fuerza aislada con recuperación completa de la autonomía.',
  'CIF es un marco descriptivo, no una prueba de eficacia de un tratamiento. Usar el instrumento elegido según su manual.',
  {scenario:'Marta, 68 años, puede elevar las piernas sentada pero necesita ayuda para cocinar de pie. Redactar un objetivo y un registro inicial.',checklist:['Diferencia función, actividad y participación','Incluye una preferencia de Marta','Describe asistencia y condiciones de medición','Define qué reevaluar']},[
   ['Marta tiene fuerza conservada en camilla pero no logra preparar el desayuno de pie. ¿Qué dato falta para planificar su rehabilitación?','Desempeño en tareas y barreras del entorno','Circunferencia del muslo al terminar la consulta','Resultado de una imagen lumbar antigua','Frecuencia de visitas prevista por la familia','Dolor en reposo como medida de toda su función','El desempeño en tareas y las barreras explican la limitación que importa a Marta. Una medida corporal aislada no representa su participación.'],
   ['Dos personas presentan igual movilidad de rodilla; una vive en planta baja y otra sube escaleras para entrar. ¿Qué cambia en la evaluación?','Las demandas funcionales y ambientales','La interpretación anatómica de la rodilla','La escala de dolor para el mismo síntoma','La definición del rango articular medido','El diagnóstico radiológico por domicilio','Las demandas funcionales y ambientales pueden generar necesidades diferentes aun con la misma alteración corporal. El objetivo debe reflejar la vida cotidiana.'],
   ['¿Cuál de estas metas permite evaluar mejor el avance de una paciente que quiere volver a cocinar?','Preparar una merienda con el apoyo acordado','Mejorar globalmente el estado musculoesquelético','Aumentar veinte grados una medición sin vincularla a tareas','Completar la rutina del profesional tratante','Alcanzar una sensación general de bienestar','Preparar una merienda con el apoyo acordado conecta una actividad concreta con la meta personal. Hay que agregar plazo y condiciones después de la evaluación basal.'],
   ['Un colega propone quitar preguntas de WHODAS y conservar la puntuación total original. ¿Qué respuesta es adecuada?','Usar una versión validada según su manual','Promediar los ítems quitados con el dolor','Completar los ítems faltantes con ceros','Comparar el resultado con el total original','Reemplazar las preguntas por fuerza muscular','Usar una versión validada preserva la interpretación de WHODAS. Quitar ítems y conservar el total produce una medida distinta, sin equivalencia demostrada.']]),
 lesson(clinical,2,'Seguridad y señales de alarma',['kin-redflags','kin-ng59'],'Reconocer cuándo corresponde detener la evaluación y derivar.',
  'Antes de cargar, movilizar o ejercitar, preguntá por cambios recientes que puedan modificar la prioridad. En dolor lumbar irradiado, una alteración nueva de la función vesical, intestinal o sexual, o adormecimiento perineal, exige evaluación inmediata por posible compromiso de cauda equina. El rol inicial es reconocer y activar el circuito, sin esperar que aparezcan todos los signos.\n\nNo conviertas una lista de alarmas en un diagnóstico automático. Documentá qué cambió, cuándo comenzó, si progresa y qué evaluación se realizó. Una persona puede tener una causa urgente aunque conserve parte de su marcha. Una etiqueta antigua de lumbalgia tampoco explica necesariamente síntomas nuevos. Si hay deterioro agudo durante la sesión, interrumpí el ejercicio y solicitá asistencia conforme al protocolo del centro.\n\nPara practicar el pase, ordená cuatro datos: problema actual, antecedentes relevantes, hallazgos y solicitud concreta. Por ejemplo: «Dolor irradiado con dificultad nueva para orinar desde hoy; se interrumpió la sesión y se solicita evaluación urgente». Registrá a quién avisaste y la respuesta. Explicá a la persona por qué cambia el plan y verificá que llegue al recurso indicado. Las alarmas neurológicas no se resuelven probando una técnica manual para ver si mejora.',
  'Esperar a completar una rutina cuando los síntomas nuevos cambiaron el riesgo.',
  'Recomendación de derivación de NICE NG127; el diagnóstico y los estudios corresponden al equipo que evalúa la urgencia.',
  {scenario:'Paciente con dolor irradiado presenta desde la mañana dificultad urinaria y adormecimiento perineal. Ensayar comunicación y derivación.',checklist:['Identifica síntomas nuevos','Interrumpe la sesión','Activa evaluación inmediata','Confirma recepción del pase']},[
   ['Con lumbociatalgia, un adulto refiere desde hoy retención urinaria y adormecimiento perineal. ¿Qué hacés primero?','Activar evaluación urgente por posible cauda equina','Programar control kinésico dentro de una semana','Probar extensión lumbar y reevaluar al finalizar','Solicitar un diario miccional antes de derivarlo','Indicar reposo domiciliario hasta el día siguiente','Activar evaluación urgente responde a la combinación de dolor irradiado y cambios esfinterianos/perineales nuevos. Probar ejercicio primero puede retrasar la atención.'],
   ['La persona con síntomas urinarios nuevos todavía puede caminar. ¿Cómo modifica eso el pase por sospecha neurológica?','Mantiene la necesidad de evaluación inmediata','Permite postergar la consulta hasta perder fuerza','Descarta compromiso si sube un escalón','Convierte el cuadro en dolor mecánico benigno','Sustituye el examen por una prueba de marcha','La marcha conservada no descarta una urgencia neurológica. La necesidad de evaluación inmediata se sostiene por los síntomas nuevos descritos.'],
   ['¿Qué información vuelve más útil una derivación por dolor lumbar con alarma neurológica?','Síntomas nuevos, inicio, evolución y solicitud','Intensidad actual sin evolución ni síntomas asociados','Diagnóstico antiguo y ejercicios preferidos','Intensidad del dolor sin datos temporales','Respuesta a masajes previos sin precisar el cambio reciente','Síntomas nuevos, inicio y evolución permiten al receptor priorizar el problema. Una solicitud explícita y su recepción cierran la comunicación.'],
   ['Durante la entrevista aparece adormecimiento perineal nuevo en una lumbalgia irradiada. ¿Qué afirmación describe tu conclusión?','Hay una sospecha que requiere evaluación urgente','La cauda equina está confirmada por la entrevista','La ausencia de imagen impide comunicar el riesgo','El síntoma determina cirugía antes de la evaluación','La fuerza conservada permite descartar la sospecha','Hay una sospecha que requiere evaluación urgente, no un diagnóstico confirmado. Reconocer incertidumbre no justifica demorar el circuito de atención.']]),
 lesson(clinical,3,'Dolor lumbar: educación y actividad',['kin-lbp','kin-ng59'],'Construir un plan activo para lumbalgia primaria crónica sin alarmas.',
  'La guía OMS 2023 aborda dolor lumbar primario crónico en adultos en atención primaria y comunitaria. Ese alcance no incluye asumir que toda lumbalgia sea primaria ni aplicar el mismo plan a una urgencia neurológica. Una vez evaluadas causas específicas y riesgos, el manejo integra información comprensible, ejercicio y decisiones centradas en la persona.\n\nUna imagen no explica de forma completa la experiencia de dolor ni la capacidad para moverse. La evaluación clínica orienta si un estudio adicional cambiaría la conducta. En un caso sin señales de alarma, explicá que la recuperación funcional se puede trabajar mediante actividades tolerables y progresivas. No prometas que un ejercicio «recoloca» de manera permanente una estructura ni que elimina el dolor en un número fijo de sesiones.\n\nEjercicio docente: Tomás evita levantar una bolsa liviana por miedo. Primero explorá qué teme y qué actividad necesita recuperar. Acordá una versión accesible de esa tarea, una forma de registrar respuesta y una fecha de revisión. Si las molestias o la función empeoran de manera persistente, revisá dosis y evaluación. Las técnicas manuales, cuando se eligen, se integran a un plan que incluye ejercicio; el alivio transitorio no reemplaza el desarrollo de autonomía. Cerrá la sesión pidiendo al paciente que explique su plan con sus propias palabras.',
  'Usar la imagen como pronóstico inevitable o convertir el tratamiento pasivo en el único objetivo.',
  'Guía OMS para dolor lumbar primario crónico; NICE respalda ejercicio y terapia manual dentro de un paquete con ejercicio. No se extrapola a patología específica.',
  {scenario:'Tomás, 39 años, lumbalgia de cuatro meses sin alarmas tras evaluación, teme levantar compras. Diseñar un inicio de actividad compartido.',checklist:['Comprueba alcance del diagnóstico','Explora miedo y meta','Propone tarea graduada','Acuerda reevaluación']},[
   ['Tomás tiene lumbalgia primaria crónica sin alarmas y dejó de llevar compras por temor. ¿Qué propuesta es más apropiada?','Acordar actividad gradual con educación y revisión','Indicar inmovilidad hasta que el dolor desaparezca','Aplicar terapia pasiva sin objetivos funcionales','Solicitar imagen como requisito para cada ejercicio','Prometer recuperación con una maniobra correctiva','Acordar actividad gradual con educación ayuda a recuperar una tarea relevante. La revisión permite adaptar el plan; inmovilidad o promesas estructurales no resuelven esa necesidad.'],
   ['Un informe lumbar describe cambios degenerativos; la función mejora y no hay síntomas nuevos. ¿Qué dato debe pesar al progresar?','La respuesta clínica y funcional al plan','La palabra degenerativo del informe previo','La antigüedad administrativa de la radiografía','La edad como sustituto de evaluación física','La cantidad de hallazgos escritos en el informe','La respuesta clínica y funcional debe guiar la progresión junto con la seguridad. Un hallazgo de imagen aislado no fija la capacidad ni el pronóstico individual.'],
   ['Una paciente siente alivio con terapia manual y pregunta si puede abandonar el componente activo. ¿Qué explicás?','Integrar el alivio al programa con ejercicio','Sustituir ejercicio por sesiones manuales indefinidas','Elegir la técnica según el ruido articular','Mantener el componente pasivo como meta funcional','Medir éxito por cantidad de maniobras realizadas','Integrar el alivio al programa con ejercicio conserva el objetivo de función y autonomía. NICE sitúa la terapia manual dentro de un paquete que incluye ejercicio.'],
   ['¿A cuál situación corresponde directamente la guía OMS de dolor lumbar primario crónico utilizada en este tema?','Adulto en atención comunitaria con cuadro primario crónico','Niño con trauma lumbar y déficit progresivo de fuerza','Adulto con sospecha nueva de infección vertebral','Paciente posoperatorio con restricción quirúrgica específica','Persona con retención urinaria aguda y anestesia perineal','El alcance es el adulto con dolor lumbar primario crónico en atención primaria/comunitaria. Las otras situaciones requieren evaluación y recomendaciones específicas.']]),
 lesson(clinical,4,'Ejercicio terapéutico en artrosis',['kin-oa'],'Dosificar, explicar y ajustar ejercicio según respuesta funcional.',
  'En artrosis, el ejercicio terapéutico adaptado a las necesidades es un componente central: puede incluir fortalecimiento local y actividad aeróbica. El plan se construye con la persona y considera acceso, preferencias y capacidad actual. Un aumento inicial de molestias no prueba por sí solo daño articular, pero tampoco debe usarse para ignorar una reacción importante o un cambio de patrón.\n\nLa prescripción se registra con frecuencia, intensidad, tiempo y tipo de actividad, además de asistencia y descansos. En este curso esos campos son una herramienta de documentación, no una receta universal. Un ejemplo de comienzo puede consistir en practicar una tarea funcional con menos carga o más apoyo; el profesional define la dosis tras evaluar. Registrá síntomas durante la tarea, recuperación posterior y efecto en la vida diaria.\n\nSi la persona no sostiene el plan, preguntá por barreras concretas antes de llamarlo falta de voluntad: horario, miedo, dolor, espacio o necesidad de cuidar a otros. Acordá una alternativa que conserve el objetivo. En la revisión, compará tolerancia, función y adherencia real. Progresá una variable a la vez para entender qué cambió. Si aparece una articulación agudamente caliente o un cuadro distinto al habitual, corresponde reevaluación clínica y no aumentar carga automáticamente.',
  'Prescribir por el grado radiológico sin medir función, o aumentar simultáneamente todas las variables.',
  'NICE NG226 recomienda ejercicio personalizado; no establece una única rutina para todas las personas con artrosis.',
  {scenario:'Elena tiene artrosis de rodilla, mejor tolerancia al levantarse, pero abandonó una rutina difícil de hacer en casa. Reformular el plan.',checklist:['Define meta funcional','Describe dosis y apoyo','Explora barreras reales','Planifica control de respuesta']},[
   ['Elena mejora al levantarse de la silla, pero no cumple una rutina extensa. ¿Qué cambio favorece un plan sostenible?','Acordar tareas accesibles conservando la meta','Aumentar ejercicios para recuperar lo no realizado','Suspender el fortalecimiento por falta de adherencia','Cambiar la meta a completar sesiones pagadas','Elegir intensidad por el grado radiológico previo','Acordar tareas accesibles responde a las barreras reales y conserva la meta funcional. Agregar más carga sin explorar el problema puede empeorar la adherencia.'],
   ['Una persona con artrosis pregunta qué registrar además del nombre de cada ejercicio. ¿Qué conjunto permite ajustar la dosis?','Frecuencia, intensidad, tiempo y respuesta','Dolor basal y edad sin registrar la carga aplicada','Diagnóstico e imagen sin describir ejecución ni dosis','Rango articular sin registrar cómo se entrenó','Intensidad máxima sin tiempo ni recuperación posterior','Frecuencia, intensidad, tiempo y respuesta permiten reconstruir la dosis y ajustarla. El tipo de actividad, los descansos y la ayuda también deben quedar documentados.'],
   ['Tras iniciar ejercicio aparece molestia leve transitoria, sin pérdida funcional. ¿Cómo lo interpretás?','Revisar tolerancia y evolución antes de ajustar','Confirmar daño progresivo de cartílago por dolor','Suspender indefinidamente cualquier carga articular','Duplicar carga para acelerar la adaptación','Pedir imagen antes de conversar sobre síntomas','Revisar tolerancia y evolución evita equiparar cada molestia con daño. La respuesta posterior y la función ayudan a decidir si se mantiene o adapta la dosis.'],
   ['En un control aparece rodilla caliente y muy dolorosa con un cambio marcado respecto del patrón habitual. ¿Cuál es la prioridad?','Reevaluar el cuadro antes de continuar la carga','Continuar porque la artrosis explica todo dolor','Progresar intensidad según la agenda original','Repetir sentadillas para confirmar tolerancia máxima','Esperar al próximo mes para comparar función','Reevaluar el cuadro reconoce que un cambio agudo no debe atribuirse automáticamente a artrosis. Continuar la carga sin revisar la causa puede ser inadecuado.']]),
 lesson(clinical,5,'Caídas, autonomía y continuidad',['kin-falls','kin-icf'],'Integrar movilidad, entorno y comunicación en un plan de prevención.',
  'Una caída requiere comprender cómo ocurrió, qué cambió y qué factores pueden repetirse. La prevención no se reduce a medir fuerza: incluye marcha y equilibrio, capacidad funcional, entorno y otros factores que necesitan evaluación interdisciplinaria. La revisión de medicación o causas cardiovasculares se coordina con los profesionales responsables.\n\nEn personas para quienes está indicado, el ejercicio se adapta a sus necesidades, con trabajo dirigido a equilibrio, coordinación, fuerza y potencia. La supervisión y progresión dependen del riesgo y de la capacidad para realizar las tareas. No se debe usar una prueba única para decidir que alguien es completamente seguro. Tampoco se debe entrenar una tarea desafiante sin preparar el ambiente y la ayuda necesaria.\n\nCaso de trabajo: Roberto se tropieza al ir al baño de noche y se levanta con mareo. El plan debe contemplar una evaluación del mareo, el trayecto, la iluminación y las transferencias, además del ejercicio. En la nota de alta describí qué puede hacer, con qué apoyo, qué sigue pendiente y quién continuará el seguimiento. Pedí que la persona o cuidador muestre cómo entendió el plan. Definí una vía de contacto ante nuevas caídas o deterioro y medí resultados en actividades significativas, no sólo en asistencia a sesiones.',
  'Concluir que un buen resultado de fuerza descarta el riesgo de caídas.',
  'NICE NG249: abordaje integral y ejercicio personalizado en la población y el ámbito indicados; la valoración de causas médicas se coordina.',
  {scenario:'Roberto, 77 años, cayó al ir al baño y refiere mareos al ponerse de pie. Preparar un plan y un pase al equipo.',checklist:['Reconstruye la caída','Reconoce el mareo como dato a evaluar','Considera entorno y apoyo','Entrega un seguimiento concreto']},[
   ['Roberto cae de noche, refiere mareos al incorporarse y tiene buena fuerza en camilla. ¿Qué enfoque corresponde?','Evaluar múltiples factores y coordinar el mareo','Descartar riesgo por la fuerza muscular conservada','Indicar fortalecimiento como única evaluación inicial','Restringir toda marcha sin analizar el episodio','Medir el éxito por no salir del dormitorio','Evaluar múltiples factores incluye el mareo, el entorno y las tareas. La fuerza conservada no explica ni descarta el mecanismo de la caída.'],
   ['¿Qué información hace más útil el alta kinésica de una persona con riesgo de caídas?','Tareas posibles, ayuda requerida y seguimiento','Rango articular final sin describir tareas cotidianas','Fuerza aislada sin necesidades de ayuda en domicilio','Diagnóstico de ingreso sin evolución funcional','Rutina genérica sin criterios de ajuste ni contacto','Tareas posibles, ayuda requerida y seguimiento permiten continuar cuidados y organizar apoyos. El listado de técnicas no comunica autonomía ni riesgos pendientes.'],
   ['Una familia pide entrenar equilibrio con ojos cerrados sin supervisión porque vio un video. ¿Qué respuesta es adecuada?','Elegir un desafío seguro según evaluación y apoyo','Copiar la dificultad del video para ganar confianza','Mantener el ejercicio si existe una silla cercana','Compensar el riesgo haciendo más repeticiones','Elegir tareas por edad sin evaluar desempeño','Elegir un desafío seguro exige evaluar capacidad, entorno y apoyo. Un video no determina la dificultad apropiada para una persona con riesgo de caídas.'],
   ['El paciente asiente al escuchar las indicaciones, pero duda al mostrar la transferencia acordada. ¿Cómo cerrás la sesión?','Practicar la explicación y comprobar comprensión','Dar por aprendido el plan por su asentimiento','Entregar más ejercicios sin revisar la transferencia','Solicitar una firma para reemplazar la demostración','Esperar una nueva caída para aclarar las dudas','Practicar la explicación y comprobar comprensión detecta dificultades concretas antes del alta. El asentimiento verbal no muestra que pueda ejecutar el plan.']])
];
const respiratoryLessons=[
 lesson(resp,1,'Evaluación respiratoria y capacidad de esfuerzo',['kin-walk','kin-oxygen'],'Relacionar síntomas, mediciones y función antes de ejercitar.',
  'La evaluación respiratoria combina disnea, patrón ventilatorio, tos, secreciones, capacidad de esfuerzo y contexto clínico. Registrá la situación basal, el soporte indicado y los cambios respecto de días previos. Una saturación aislada no informa ventilación ni sustituye la observación del paciente. Si la persona se deteriora, el objetivo pasa de medir rendimiento a evaluar y atender el cambio.\n\nLa prueba de marcha de seis minutos mide desempeño funcional bajo condiciones estandarizadas; no equivale a una prueba máxima ni identifica por sí sola la causa de la limitación. Para comparar resultados deben mantenerse recorrido, instrucciones, ayudas y condiciones de oxígeno, documentando cualquier diferencia. El centro debe disponer del protocolo completo, personal competente y respuesta ante eventos. Dolor torácico, presíncope u otros síntomas preocupantes exigen detener y evaluar.\n\nEjercicio de lectura: Ana caminó menos metros que antes, pero esta vez utilizó otro recorrido y una ayuda distinta. Antes de concluir deterioro, verificá la comparabilidad. Anotá distancia, pausas, síntomas, respuesta fisiológica y condiciones. Después preguntá qué limita sus actividades habituales: una medición tiene sentido si ayuda a elegir y revisar el plan. No se modifica el oxígeno indicado para hacer que el resultado parezca mejor; cualquier ajuste clínico se decide por seguridad y se registra.',
  'Interpretar metros o SpO₂ sin las condiciones de medición ni la clínica.',
  'ATS 2002 aporta el estándar fundacional; utilizar el protocolo técnico actualizado adoptado por el centro. Los objetivos de oxígeno son clínicos, no metas de rendimiento.',
  {scenario:'Comparar dos pruebas de Ana realizadas con recorridos y ayudas diferentes. Elegir qué conclusiones sí se pueden sostener.',checklist:['Verifica condiciones','Integra síntomas y mediciones','Evita atribuir causa por distancia','Registra la limitación interpretativa']},[
   ['Ana caminó 40 metros menos, pero cambió recorrido y bastón entre evaluaciones. ¿Qué concluís primero?','La comparación tiene condiciones diferentes','El descenso confirma progresión pulmonar','La diferencia demuestra pérdida muscular','El nuevo bastón explica toda la variación','La menor distancia confirma desmotivación','La comparación tiene condiciones diferentes y no permite atribuir automáticamente el descenso a progresión. El registro debe aclarar recorrido, ayudas y soporte.'],
   ['Durante una prueba de marcha aparece dolor torácico nuevo y presíncope. ¿Qué corresponde?','Detener y activar evaluación clínica','Reducir el paso hasta completar seis minutos','Repetir la medición antes de comunicar síntomas','Esperar al final para decidir si fue relevante','Cambiar el recorrido por uno más corto','Detener y activar evaluación clínica prioriza síntomas potencialmente importantes. Completar una medición no justifica continuar ante dolor torácico y presíncope.'],
   ['¿Qué expresa principalmente la distancia de una marcha de seis minutos estandarizada?','Desempeño funcional bajo esas condiciones','Diagnóstico específico de obstrucción pulmonar','Consumo máximo de oxígeno medido directamente','Ausencia de enfermedad cardiovascular relevante','Capacidad para retirar oxígeno de forma autónoma','La distancia representa desempeño funcional bajo condiciones definidas. No determina por sí sola etiología, consumo máximo ni indicación de oxígeno.'],
   ['Una SpO₂ aparentemente normal acompaña respiración trabajosa y somnolencia nueva. ¿Qué dato orienta la conducta?','El deterioro clínico exige reevaluación','La saturación descarta falla ventilatoria','La somnolencia confirma sueño reparador','La lectura permite completar el esfuerzo','El valor justifica retirar toda monitorización','El deterioro clínico exige reevaluación: la SpO₂ no mide ventilación ni excluye hipercapnia. El número no debe desplazar la observación del paciente.']]),
 lesson(resp,2,'Rehabilitación pulmonar: selección y componentes',['kin-pr'],'Distinguir rehabilitación pulmonar integral de una técnica aislada.',
  'La rehabilitación pulmonar combina evaluación individual, entrenamiento, educación y apoyo al autocuidado. La guía ATS 2023 recomienda su participación en EPOC estable, después de hospitalización por exacerbación de EPOC y en enfermedad pulmonar intersticial; para hipertensión pulmonar la recomendación es condicional. Esto no significa aplicar una misma intensidad o contexto a todos.\n\nEl programa comienza por necesidades y objetivos: por ejemplo, llegar a una parada o ducharse con menos limitación. Se registran tolerancia, comorbilidades, barreras de acceso y capacidad de reconocer cambios clínicos. No basta con entregar ejercicios respiratorios; también hay que enseñar cómo se seguirá el progreso y a quién consultar. Una persona recién egresada requiere comprobar estabilidad y coordinación con el equipo, no asumir que ya tolera cualquier esfuerzo.\n\nPara enfermedad respiratoria crónica estable, ATS respalda ofrecer la elección entre centro y telerehabilitación. La elección necesita valorar recursos, comprensión y posibilidad de seguimiento. Una videollamada aislada no equivale a un programa. Caso docente: Luis vive lejos y tiene conexión intermitente. Proponer modalidad remota implica resolver cómo recibirá instrucciones, cómo comunicará síntomas y cuándo habrá contacto presencial. La preferencia del paciente participa en la decisión; el lugar de prestación no elimina la evaluación inicial ni la necesidad de un plan individual.',
  'Llamar rehabilitación pulmonar a una única técnica o a una rutina idéntica para todos.',
  'ATS 2023: recomendaciones fuertes para EPOC estable/poshospitalización y enfermedad intersticial; condicional para hipertensión pulmonar.',
  {scenario:'Luis, con EPOC estable, quiere retomar compras y vive lejos. Diseñar un programa y comparar una modalidad presencial con una remota.',checklist:['Incluye entrenamiento y educación','Define una meta funcional','Evalúa acceso y seguridad','Acuerda seguimiento']},[
   ['¿Qué propuesta representa mejor rehabilitación pulmonar para EPOC estable?','Evaluación, entrenamiento, educación y seguimiento','Entrega de un espirómetro sin evaluación posterior','Sesiones de masaje torácico como tratamiento completo','Caminar sin metas ni seguimiento','Una videollamada para mostrar respiración diafragmática','Evaluación, entrenamiento, educación y seguimiento forman un programa integral. Un dispositivo o una técnica aislada no cubren los componentes de rehabilitación.'],
   ['Una persona egresa tras exacerbación de EPOC y consulta por rehabilitación. ¿Qué enfoque es coherente con ATS 2023?','Coordinar ingreso tras valorar estabilidad y necesidades','Excluirla del programa por haber sido hospitalizada','Esperar una nueva exacerbación para considerar ingreso','Prescribir intensidad máxima por el tiempo de internación','Limitar el programa a cambiar la medicación inhalada','Coordinar ingreso reconoce la recomendación de rehabilitación después de hospitalización por exacerbación. La estabilidad y necesidades determinan cómo se implementa.'],
   ['Luis tiene enfermedad estable y prefiere telerehabilitación. ¿Qué necesitás comprobar?','Recursos, comprensión y seguimiento seguro','Que la distancia elimine la evaluación inicial','Que toda sesión presencial pueda omitirse por regla','Que el teléfono sustituya el plan','Que el oxímetro determine todas las decisiones','Recursos, comprensión y seguimiento seguro hacen viable la modalidad. ATS respalda ofrecer elección en enfermedad estable, sin eliminar evaluación ni individualización.'],
   ['¿Cómo se interpreta la recomendación ATS de rehabilitación en hipertensión pulmonar frente a EPOC estable?','Es condicional y requiere mayor contextualización','Es una prohibición de cualquier actividad física','Tiene el mismo respaldo que todo ejercicio competitivo','Autoriza usar la dosis de EPOC sin evaluación','Equivale a una garantía de reducción de mortalidad','Es condicional: la decisión requiere considerar incertidumbre, características individuales y equipo tratante. No equivale a prohibición ni a garantía de un desenlace.']]),
 lesson(resp,3,'Higiene bronquial individualizada',['kin-ers','kin-bts'],'Elegir y reevaluar técnicas según enfermedad, tolerancia y preferencias.',
  'En bronquiectasias, ERS 2025 recomienda enseñar técnicas de limpieza bronquial mediante personal con experiencia. Es una recomendación fuerte con certeza muy baja de la evidencia: la fuerza de una recomendación y la certeza no son sinónimos. Ninguna técnica ha demostrado superioridad universal; la elección debe adaptarse a la persona.\n\nEl ciclo activo de respiración, la espiración forzada o huff y los dispositivos de presión espiratoria son opciones que requieren enseñanza y observación. Antes de elegir, revisá tos, capacidad para expulsar secreciones, fatiga, dolor, reflujo y preferencias. BTS describe alternativas de posición cuando el declive no se tolera. Si hay hemoptisis o cambios importantes, se reevalúa el cuadro y la técnica con el equipo; no se intensifica por rutina.\n\nCaso docente: Julia tiene bronquiectasias y abandona una posición por reflujo. El problema no se resuelve exigiendo adherencia a esa postura. Explorar una alternativa sentada y comprobar su ejecución permite mantener el objetivo con mejor tolerancia. Registrá efecto, síntomas y facilidad de uso. No extrapoles una recomendación específica para bronquiectasias a cualquier persona con disnea. Tampoco indiques aspiración de vía aérea artificial a quien respira espontáneamente sin una indicación y evaluación específicas.',
  'Elegir la técnica más aparatosa sin comprobar indicación, aprendizaje o tolerancia.',
  'ERS 2025 actualiza la indicación de enseñanza; BTS aporta detalles prácticos. No hay una técnica superior para todas las personas.',
  {scenario:'Julia interrumpe drenaje por reflujo. Simular entrevista, elección de alternativa y comprobación del aprendizaje sin maniobras sobre compañeros.',checklist:['Explora tolerancia','Relaciona técnica con objetivo','Revisa ejecución','Reconoce cuándo reevaluar']},[
   ['Julia con bronquiectasias presenta reflujo al adoptar declive. ¿Qué ajuste tiene mejor fundamento?','Revisar la posición y enseñar una alternativa tolerada','Mantener el declive para completar el tiempo previsto','Aumentar la inclinación para movilizar más secreciones','Abandonar toda limpieza por intolerancia a una postura','Cambiar el objetivo a medir fuerza de miembros','Revisar la posición y enseñar una alternativa tolerada mantiene el objetivo de limpieza bronquial. La intolerancia a una postura no invalida todas las técnicas.'],
   ['La guía ERS 2025 recomienda enseñar limpieza bronquial con fuerza alta y certeza muy baja. ¿Cómo lo explicás?','Integra beneficios e incertidumbre para decidir','La certeza muy baja demuestra ausencia de beneficio clínico','La fuerza de la recomendación reemplaza la evaluación individual','Garantiza igual beneficio en todos','La fuerza equivale a resultados de ensayos sin limitaciones','La recomendación integra beneficios, valores, accesibilidad e incertidumbre. Su fuerza no transforma la certeza muy baja en evidencia sin limitaciones.'],
   ['Un paciente pide el dispositivo más costoso porque espera que sea superior. ¿Qué respuesta corresponde?','Seleccionar técnica según evaluación y preferencias','Elegir el precio como indicador de eficacia clínica','Sustituir enseñanza por instrucciones del fabricante','Usar el dispositivo más nuevo en todos los pacientes','Mantener una técnica aunque produzca mala tolerancia','Seleccionar según evaluación y preferencias respeta la ausencia de superioridad universal. El aprendizaje y la tolerancia importan más que el precio del dispositivo.'],
   ['Aparece hemoptisis nueva durante un programa habitual de higiene bronquial. ¿Cuál es la siguiente decisión?','Reevaluar el cuadro y la técnica con el equipo','Aumentar intensidad para terminar la limpieza','Mantener la rutina porque la técnica ya fue enseñada','Cambiar de dispositivo sin comunicar el episodio','Registrar el dato sólo en el control mensual','Reevaluar el cuadro y la técnica reconoce un cambio clínico que puede modificar el plan. Aumentar intensidad o cambiar el dispositivo no sustituye esa valoración.']]),
 lesson(resp,4,'Monitorización y ajuste del esfuerzo',['kin-oxygen','kin-pr'],'Interpretar tendencias y síntomas para adaptar la sesión.',
  'La sesión se prepara con una meta funcional, una dosis inicial y criterios para modificarla. Registrá síntomas, respuesta cardiovascular y oxigenación cuando corresponda. El esfuerzo percibido y la disnea ayudan a interpretar tolerancia, pero no reemplazan la evaluación de eventos nuevos. Compará con la situación basal y el objetivo indicado, no con un número universal.\n\nLa guía AARC de oxígeno para adultos hospitalizados propone 94–98% para la mayoría y 88–92% en EPOC; estos rangos pertenecen a ese contexto y no constituyen por sí solos una prescripción domiciliaria o una autorización para aumentar cargas. En la sesión debe conocerse el objetivo individual y el plan de escalamiento. La oximetría se interpreta con calidad de señal y clínica. Si hay desaturación relevante o síntomas preocupantes, interrumpí el esfuerzo y evaluá; no atribuyas el cambio al sensor sin comprobarlo.\n\nUn ejemplo de ajuste es dividir una tarea en intervalos si el equipo considera que sigue siendo apropiada. Documentá duración, pausas y recuperación para poder comparar. Si la tolerancia cae varios días, revisá posibles cambios clínicos y barreras, en lugar de subir intensidad para recuperar una meta atrasada. El resultado buscado es avanzar de manera sostenible hacia una actividad valiosa para la persona.',
  'Usar una saturación deseada como permiso para forzar ejercicio o ajustar oxígeno fuera del plan clínico.',
  'AARC 2022 se refiere a hospitalización; los objetivos y acciones concretas se individualizan. ATS orienta la rehabilitación integral.',
  {scenario:'Durante una sesión se registra menor tolerancia y saturación fuera del objetivo individual. Ensayar una pausa, evaluación y comunicación.',checklist:['Compara con basal y objetivo','Valora clínica y señal','Detiene ante deterioro','Registra respuesta y comunica']},[
   ['En ejercicio cae la SpO₂ fuera del objetivo indicado y aparece mayor disnea. ¿Qué hacés?','Pausar y evaluar el cambio con el plan clínico','Seguir hasta completar las repeticiones indicadas','Corregir el número subiendo carga muscular','Asumir error del sensor por estar en movimiento','Usar el promedio semanal para decidir al terminar','Pausar y evaluar integra la señal con la disnea y el objetivo individual. No corresponde ignorar el cambio ni perseguir el número para completar una rutina.'],
   ['¿Qué limita extrapolar el rango AARC de oxígeno a un plan domiciliario?','La guía citada corresponde a adultos hospitalizados','El rango determina el diagnóstico funcional completo','La saturación reemplaza la prescripción individual','El oxímetro permite modificar cualquier tratamiento','La misma meta sirve para todo tipo de esfuerzo','La guía citada corresponde a adultos hospitalizados. Una prescripción domiciliaria y su ajuste requieren contexto, evaluación y un plan específico.'],
   ['Una persona tolera una tarea al dividirla en períodos con descanso. ¿Qué registro permite evaluar ese ajuste?','Duración, pausas, síntomas y recuperación','Número de bloques sin registrar descanso entre ellos','Nombre del ejercicio realizado','Saturación final omitiendo lo ocurrido durante','Impresión de esfuerzo del profesional sin datos','Duración, pausas, síntomas y recuperación describen la dosis real y su tolerancia. La saturación final aislada puede ocultar dificultades durante la tarea.'],
   ['La tolerancia empeora durante varios días a igual carga. ¿Qué estrategia es más razonable?','Reevaluar evolución clínica y barreras del plan','Aumentar carga para recuperar el objetivo semanal','Mantener dosis sin preguntar por síntomas nuevos','Atribuir el cambio a desinterés en la rehabilitación','Cambiar la escala para mantener puntajes','Reevaluar evolución clínica y barreras permite identificar por qué cambió la respuesta. Aumentar carga automáticamente puede agravar una situación no reconocida.']]),
 lesson(resp,5,'Autocuidado, pos-COVID y seguimiento',['kin-postcovid','kin-whodas'],'Reconocer exacerbación posesfuerzo y elaborar un plan de seguimiento.',
  'La recuperación respiratoria se evalúa también fuera del consultorio. Preguntá qué ocurre después de la actividad, no sólo durante la sesión. En condición pos-COVID puede existir exacerbación de síntomas posesfuerzo (PESE): empeoramiento tras esfuerzos que antes eran tolerables. La OMS recomienda educación y estrategias de conservación de energía, como pacing, para este problema. El ejercicio no se progresa automáticamente en presencia de PESE.\n\nUn diario simple puede registrar actividad, descanso y evolución posterior para reconocer patrones. No se trata de obligar a alcanzar una cuota fija aunque aparezca deterioro. Si hay dolor torácico, síncope u otros datos preocupantes, corresponde evaluación clínica específica; no todo síntoma se explica por desacondicionamiento. La intervención se adapta a síntomas, necesidades y contexto.\n\nCaso docente: Paula completa una caminata breve en consulta, pero al día siguiente no puede realizar tareas habituales. Si sólo se observa el rendimiento inmediato, se pierde el dato decisivo. Acordá un plan de actividad y descansos que considere esa respuesta, identificá cuándo pedir ayuda y coordiná seguimiento. WHODAS puede apoyar una visión amplia de función cuando se utiliza correctamente, sin sustituir la entrevista. Al alta, entregá objetivos, forma de contacto y criterios para volver antes de lo previsto.',
  'Interpretar toda fatiga como falta de entrenamiento y prescribir aumentos fijos de ejercicio.',
  'OMS diferencia PESE de una respuesta de esfuerzo habitual y recomienda adaptar rehabilitación. El curso no diagnostica pos-COVID ni sus complicaciones.',
  {scenario:'Paula empeora al día siguiente de caminar aunque durante la sesión parecía tolerarlo. Diseñar preguntas y un seguimiento.',checklist:['Pregunta por respuesta diferida','Considera PESE','Evita progresión fija','Acuerda registro y reevaluación']},[
   ['Paula con condición pos-COVID empeora de forma marcada al día siguiente del ejercicio. ¿Qué dato debe cambiar el plan?','La respuesta diferida compatible con PESE','El buen rendimiento observado durante la sesión','La edad como garantía de tolerancia al esfuerzo','La duración breve como prueba de seguridad','El objetivo semanal pactado antes del empeoramiento','La respuesta diferida compatible con PESE obliga a adaptar el plan. Tolerar una sesión en el momento no garantiza tolerancia en los días posteriores.'],
   ['¿Qué estrategia es coherente ante PESE identificada por el equipo?','Conservación de energía y pacing individualizado','Incrementos fijos de carga aunque empeoren síntomas','Reposición de sesiones perdidas con doble esfuerzo','Entrenamiento intenso para demostrar tolerancia','Suspender seguimiento por falta de respuesta rápida','Conservación de energía y pacing individualizado ayudan a adaptar actividades. Los incrementos fijos que ignoran el empeoramiento no respetan este patrón.'],
   ['En un registro de rehabilitación pos-COVID, ¿qué dato aporta algo que no muestra el oxímetro al finalizar?','Efecto de la actividad en días posteriores','El valor máximo de SpO₂ registrado durante la sesión','Frecuencia cardíaca antes de empezar','La fuerza medida inmediatamente después del ejercicio','La distancia completada sin observar recuperación posterior','El efecto de la actividad en días posteriores permite reconocer deterioro diferido. La oximetría final no representa toda la experiencia ni la recuperación funcional.'],
   ['Durante seguimiento aparece síncope nuevo tras esfuerzo. ¿Cómo se aborda antes de ajustar el ejercicio?','Solicitar evaluación clínica del nuevo síntoma','Atribuirlo a desacondicionamiento por pos-COVID','Resolverlo duplicando descansos sin comunicarlo','Usar una prueba máxima para reproducir el episodio','Esperar a completar el diario de treinta días','Solicitar evaluación clínica del síncope nuevo evita atribuir un posible evento relevante a desacondicionamiento. El diagnóstico previo no explica automáticamente todos los cambios.']])
];
const icuLessons=[
 lesson(icu,1,'Evaluación inicial en cuidados intensivos',['kin-icu','kin-icf'],'Reconocer necesidades de rehabilitación y establecer un punto de partida.',
  'La rehabilitación en UCI empieza por evaluar necesidades, riesgos y posibilidades del momento. NICE propone identificar de manera temprana problemas físicos y no físicos, acordar objetivos y revisar el plan durante las transiciones. Preguntá por función previa, ayudas habituales, entorno y preferencias, recurriendo a familiares cuando corresponde. Estar vivo y fuera de peligro inmediato no equivale a haber recuperado autonomía.\n\nLa evaluación de hoy debe considerar conciencia, capacidad de seguir instrucciones, dolor, soporte respiratorio, estado circulatorio y dispositivos. Diferenciá «no puede» de «no se pudo evaluar». Si la persona no comprende una consigna por sedación o delirium, un resultado de prueba voluntaria no puede interpretarse como fuerza muscular real. Documentá la barrera y qué observaciones sí fueron posibles.\n\nEjemplo docente: un paciente antes independiente necesita asistencia para girar en cama. La meta inicial puede ser participar en esa tarea si es clínicamente seguro; caminar por el pasillo no tiene que ser el primer objetivo. Reuní al equipo para definir qué se hará, quién ayudará y cómo se evaluará respuesta. Un registro breve y concreto facilita continuidad entre turnos: tarea, nivel de ayuda, síntomas, motivo de interrupción y próxima revisión. La evaluación se repite porque la situación crítica puede cambiar en horas.',
  'Registrar fuerza cero cuando una prueba voluntaria no fue interpretable por falta de cooperación.',
  'NICE CG83 orienta evaluación y objetivos. Las tareas y mediciones concretas requieren entrenamiento y protocolo de la unidad.',
  {scenario:'Paciente sedado, previamente independiente, aún no sigue órdenes. Preparar una nota que distinga datos observables de pruebas no evaluables.',checklist:['Reconstruye función previa','Valora cooperación','No inventa puntajes','Acuerda un objetivo de corto plazo']},[
   ['Una persona sedada no sigue órdenes para una prueba de fuerza. ¿Qué registro es correcto?','Prueba voluntaria no interpretable en este momento','Fuerza cero confirmada en todos los músculos','Debilidad adquirida en UCI confirmada por sedación','Resultado normal porque no hubo respuesta dolorosa','Puntaje estimado según edad y días de internación','Prueba voluntaria no interpretable distingue una barrera de evaluación de un déficit demostrado. La ausencia de cooperación no permite inventar fuerza ni diagnóstico.'],
   ['¿Qué información ayuda a interpretar que un paciente necesite ayuda para girar en cama?','Función previa y asistencia requerida actualmente','Diagnóstico de ingreso sin información sobre autonomía','Saturación de reposo como único indicador funcional','Días de sedación usados para estimar fuerza actual','Edad usada para inferir la capacidad previa de marcha','Función previa y asistencia actual permiten reconocer una pérdida y plantear metas. La tarea y condiciones deben describirse para comparar la evolución.'],
   ['Un paciente recién despierto participa poco en el giro. ¿Qué meta inicial es más útil?','Aumentar participación segura en esa tarea','Caminar el pasillo antes del cambio de turno','Cumplir el mismo objetivo que su vecino de cama','Llegar a un número fijo de minutos por protocolo','Lograr independencia completa en la primera sesión','Aumentar participación segura en esa tarea parte del desempeño actual. Las metas deben acordarse y revisarse, no imponerse por comparación o calendario.'],
   ['¿Qué nota permite continuar mejor una sesión en el turno siguiente?','Tarea, ayuda, respuesta y motivo de interrupción','Cantidad de técnicas sin describir la tolerancia','Texto de ejercicio realizado sin nivel de asistencia','Puntaje aislado sin condiciones de evaluación','Objetivo de alta sin datos de la sesión actual','Tarea, ayuda, respuesta y motivo de interrupción describen qué fue posible y qué limitaría la próxima sesión. Una lista de técnicas no ofrece esa información.']]),
 lesson(icu,2,'Preparación y criterios de seguridad',['kin-safety'],'Integrar dominios de riesgo antes y durante la movilización.',
  'La seguridad no se decide por un único valor. El consenso de movilización en pacientes ventilados propone integrar dominios respiratorios, cardiovasculares, neurológicos y otros, incluyendo dispositivos. La tendencia importa: un soporte estable y uno que aumenta rápidamente no representan la misma situación aunque compartan una medición puntual. Estos criterios provienen de consenso y no garantizan ausencia de eventos.\n\nAntes de iniciar, revisá la evolución con el equipo, las restricciones vigentes, el objetivo y los recursos. Asegurá fijaciones, recorrido de líneas, material y personal suficiente; asigná quién cuida la vía aérea y quién dirige. No se retiran o desconectan dispositivos para facilitar una tarea sin indicación ni procedimiento establecido. El paciente debe saber qué se propone y cómo pedir que se detenga.\n\nDurante la actividad observá tolerancia y cambios. Un incremento del trabajo respiratorio, síntomas circulatorios, alteración del estado mental o riesgo para un dispositivo requieren pausa y reevaluación conforme al protocolo. En esta formación no se ofrece un semáforo numérico universal: cada unidad debe definir criterios operativos y escalamiento. Caso docente: si aumentó el soporte vasopresor desde la última evaluación, hay que volver a discutir la actividad antes de usar el plan del día previo.',
  'Tomar una cifra estable como autorización suficiente mientras el soporte aumenta o faltan recursos.',
  'Consenso experto de Hodgson et al. 2014: orienta evaluación multidominio, no sustituye juicio clínico ni criterios locales.',
  {scenario:'Hay plan de sedestación, pero aumentó el vasopresor y falta un integrante del equipo. Revaluar la decisión en una reunión breve.',checklist:['Detecta cambios desde el plan previo','Revisa soporte y dispositivos','Verifica personal','Decide y documenta antes de iniciar']},[
   ['La presión actual está en el objetivo, pero aumentó rápidamente el soporte vasopresor. ¿Qué implica para movilizar?','Reevaluar estabilidad con el equipo antes de iniciar','Usar la cifra actual como autorización suficiente','Repetir la actividad de ayer sin nueva evaluación','Aumentar la carga para comprobar reserva circulatoria','Considerar el cambio irrelevante para la sesión','Reevaluar estabilidad integra tendencia y soporte, no sólo la cifra. El plan de ayer no describe necesariamente el riesgo actual.'],
   ['Para sentar a un paciente ventilado, el equipo no acordó quién protegerá la vía aérea. ¿Qué falta resolver?','Roles, personal y control de dispositivos','Cantidad de repeticiones de ejercicios de mano','Preferencia de música durante la movilización','Ubicación del formulario de alta ambulatoria','Número de pasos que realizará al día siguiente','Roles, personal y control de dispositivos son parte de la preparación inmediata. Una meta motora no compensa un plan incompleto de seguridad.'],
   ['Durante la movilización se tensa un catéter y aparece malestar. ¿Qué corresponde?','Pausar y asegurar al paciente y los dispositivos','Completar la transferencia antes de revisar el catéter','Desconectar la línea para ampliar el recorrido','Mantener la tracción si la saturación es aceptable','Registrar el problema después de terminar la serie','Pausar y asegurar al paciente y los dispositivos responde a un riesgo inmediato. Una saturación aceptable no garantiza seguridad mecánica de las líneas.'],
   ['¿Qué limita usar un umbral aislado como semáforo universal de movilización?','Omite la evolución del soporte y otros riesgos','Impide interpretar cualquier medición respiratoria objetiva','Permite usar una misma intensidad si el valor coincide','Obliga a descartar la opinión del equipo sobre estabilidad','Hace innecesario registrar cambios durante la actividad','Un umbral aislado no integra tendencias, contexto ni otros dominios de seguridad. La evaluación multidominio permite reconocer riesgos que una cifra no muestra.']]),
 lesson(icu,3,'Progresión funcional y respuesta',['kin-safety','kin-icf'],'Planificar una actividad proporcional a la capacidad y reevaluarla.',
  'La progresión funcional puede recorrer participación en cama, sedestación, transferencias, bipedestación y marcha, pero no es una escalera que deba completarse en cada sesión. La tarea se elige por capacidad actual, objetivo y seguridad. El nivel de asistencia forma parte del resultado: hacer una actividad con dos personas no equivale a hacerla de forma independiente.\n\nPrepará una versión más sencilla y otra posible progresión. Si la respuesta es favorable, el equipo decide si avanzar; si aparece intolerancia, se reduce o interrumpe y se evalúa el motivo. La actividad pasiva, activa asistida y activa requieren participación distinta, por lo que se registran de manera diferenciada. No se debe deducir independencia a partir del tiempo que alguien pasó sentado con apoyo.\n\nCaso docente: ayer Clara estuvo cinco minutos sentada con asistencia de dos personas; hoy logra menos tiempo pero requiere menos ayuda. No es correcto concluir empeoramiento sólo por los minutos. Compará tarea, apoyo, síntomas y objetivo. Un registro útil describe el mejor desempeño seguro y las limitaciones. Al finalizar, verificá confort, posición, dispositivos y comunicación al equipo. Preguntá también por la percepción de esfuerzo de la paciente para que la próxima decisión no dependa únicamente de la impresión del profesional.',
  'Medir progreso sólo por minutos o distancia, omitiendo ayuda, calidad y tolerancia.',
  'Aplicación docente del marco funcional y del consenso de seguridad; no propone una dosis universal ni beneficios garantizados.',
  {scenario:'Comparar dos sesiones con tiempos y asistencia distintos. Formular una conclusión prudente y el objetivo siguiente.',checklist:['Compara la misma tarea','Distingue asistencia de independencia','Integra síntomas','Justifica mantener, progresar o reducir']},[
   ['Clara tolera menos minutos sentada que ayer, pero necesita una persona en lugar de dos. ¿Cómo interpretás el cambio?','Integrar asistencia y tolerancia con el tiempo','Concluir deterioro funcional porque disminuyó el tiempo','Concluir independencia porque ahora ayuda una sola persona','Dar por alcanzado el siguiente nivel al reducir la ayuda','Omitir el nivel de asistencia para comparar sólo minutos','Integrar asistencia y tolerancia con el tiempo evita reducir el resultado a una sola variable. Menos ayuda y menos tiempo pueden reflejar cambios distintos.'],
   ['¿Cuál registro distingue mejor actividad activa asistida de movilización pasiva?','Participación de la persona y ayuda aportada','Tiempo de sesión sin observar el esfuerzo voluntario','Rango alcanzado sin distinguir quién generó el movimiento','Posición final sin describir el apoyo durante la tarea','Tiempo de internación previo a la sesión','Participación de la persona y ayuda aportada describen la naturaleza de la actividad. El tiempo o equipamiento no permiten inferir participación muscular.'],
   ['Un paciente completa sedestación con síntomas nuevos y mala tolerancia. ¿Qué decisión sigue?','Reevaluar antes de intentar el siguiente nivel','Pasar a bipedestación porque completó el tiempo','Aumentar repeticiones para alcanzar la meta diaria','Usar el logro como autorización para caminar','Omitir los síntomas si la tarea fue terminada','Reevaluar antes del siguiente nivel prioriza la respuesta real. Completar una tarea no prueba que sea seguro progresar inmediatamente.'],
   ['¿Qué debe incluir el cierre de una actividad junto a la cama?','Confort, posición, dispositivos y comunicación','Preparar la siguiente carga sin revisar la actual','Anotar minutos sin conversar con el paciente','Retirar apoyos para estimular independencia','Dar el alta funcional por tolerar la transferencia','Confort, posición, dispositivos y comunicación aseguran continuidad después del esfuerzo. La evaluación no termina al completar el movimiento.']]),
 lesson(icu,4,'Qué dice la evidencia sobre movilización',['kin-padis','kin-team'],'Interpretar recomendaciones y ensayos sin convertirlos en reglas rígidas.',
  'La actualización PADIS 2025 sugiere rehabilitación/movilización mejorada respecto del cuidado habitual; la recomendación es condicional. Mejorada puede significar organizar mejor el programa o modificar componentes, y no debe interpretarse como maximizar intensidad para todas las personas. La decisión integra contexto, tolerancia y recursos.\n\nEl ensayo TEAM estudió aumentar la movilización activa temprana durante ventilación mecánica. No encontró una mejora significativa del desenlace principal de días vivos y fuera del hospital a 180 días; los eventos potencialmente relacionados con movilización fueron más frecuentes en la intervención. Esto no demuestra que toda rehabilitación sea inútil: compara una estrategia concreta con el cuidado habitual de esos centros. Tampoco permite asumir que más minutos siempre sean mejores.\n\nAl leer un estudio formulá cuatro preguntas: quiénes participaron, qué intervención recibieron, contra qué se comparó y qué resultado se midió. Después revisá daños e incertidumbre. Ejercicio docente: un servicio quiere duplicar duración para mejorar un indicador administrativo. Antes de implementarlo debe definir el problema clínico, considerar evidencia, recursos y seguimiento de eventos. El objetivo del programa es una recuperación relevante para pacientes, no aumentar una cifra de actividad sin comprobar tolerancia y resultados.',
  'Confundir una recomendación condicional con una obligación de máxima intensidad o convertir un ensayo negativo en rechazo de toda rehabilitación.',
  'PADIS 2025 y TEAM 2022 abordan preguntas diferentes. El resumen gratuito de TEAM permite estudiar sus resultados principales, sin exigir acceso pago.',
  {scenario:'Un equipo propone duplicar minutos por paciente. Debatir qué permite y qué no permite afirmar la evidencia disponible.',checklist:['Distingue recomendación y certeza','Identifica población y comparación','Considera daños','Evita extrapolar una dosis universal']},[
   ['La unidad interpreta PADIS 2025 como obligación de máxima intensidad. ¿Cuál es la lectura más adecuada?','Recomendación condicional con adaptación individual','Orden de aumentar minutos sin considerar tolerancia','Prueba de que todos los pacientes deben caminar','Equivalencia entre dosis alta y mayor supervivencia','Exclusión de decisiones compartidas por ser una guía','La recomendación condicional exige adaptación individual y al contexto. PADIS no convierte intensidad máxima ni caminar en objetivos obligatorios para cada paciente.'],
   ['¿Qué interpretación es compatible con TEAM 2022?','Aumentar esa estrategia no mejoró el desenlace principal','Toda rehabilitación en UCI carece de utilidad clínica','La movilización de mayor dosis eliminó eventos adversos','El reposo prolongado fue demostrado como superior universal','El estudio comparó rehabilitación ambulatoria domiciliaria','Aumentar esa estrategia no mejoró el desenlace principal y hubo más eventos relacionados. El ensayo no compara toda rehabilitación con su ausencia ni prueba una regla universal.'],
   ['Un resultado muestra más sesiones, pero no informa función ni eventos. ¿Qué falta para juzgar valor clínico?','Resultados relevantes y posibles daños','Días del programa sin comparar desenlaces funcionales','Cantidad de técnicas añadidas sin evaluar tolerancia','Minutos por sesión tomados como prueba de recuperación','Porcentaje de asistencia interpretado como beneficio neto','Resultados relevantes y posibles daños permiten valorar beneficio clínico. El número de sesiones es una medida de actividad, no una demostración de recuperación.'],
   ['Antes de extrapolar un ensayo de movilización a tu UCI, ¿qué comparación es prioritaria?','Pacientes y tratamiento comparado en cada contexto','Edad promedio sin revisar la intervención comparada','Resultado principal sin considerar eventos adversos','Significación estadística sin relevancia del efecto','Conclusión del resumen sin revisar el cuidado habitual','Pacientes y tratamiento comparado en cada contexto determinan aplicabilidad. Un resultado no se transporta a otro contexto únicamente por la reputación del estudio.']]),
 lesson(icu,5,'Transición a sala y recuperación pos-UCI',['kin-icu','kin-whodas'],'Planificar continuidad funcional y detectar necesidades persistentes.',
  'Salir de UCI cambia el entorno, la monitorización y el equipo responsable. El pase debe incluir necesidades de rehabilitación y el plan acordado. La recuperación puede involucrar función física, cognición, sueño, comunicación y bienestar emocional; los problemas no físicos también pueden limitar participación. No todo se resuelve con fortalecer miembros.\n\nAntes de trasladar o dar el alta, describí tareas, ayudas, barreras y asuntos pendientes. Informá qué se practicó y cómo respondió la persona. Acordá con el equipo quién continúa cada necesidad y cómo se accederá al seguimiento. NICE CG83 propone una revisión funcional a los dos o tres meses de la salida de cuidados críticos para quienes tienen necesidades de rehabilitación; ese momento no sustituye controles anteriores si hay deterioro o problemas importantes.\n\nCaso docente: Daniel puede caminar acompañado, pero tiene miedo intenso, duerme mal y olvida indicaciones. La distancia caminada no justifica omitir estos problemas del alta. Coordiná evaluación de esas necesidades y una explicación que pueda comprender, involucrando a su cuidador con consentimiento. Entregá una forma clara de contacto y pedí que repitan el plan. El objetivo del pase es que la atención continúe, no sólo que el documento quede completo.',
  'Dar por recuperada a una persona que camina pero conserva barreras cognitivas, emocionales o de autocuidado.',
  'NICE CG83 describe continuidad y revisión funcional; la fecha orientativa no reemplaza reevaluación temprana ante cambios.',
  {scenario:'Daniel pasa a sala con ayuda para marcha, miedo y dificultad para recordar instrucciones. Preparar el pase y la continuidad.',checklist:['Incluye dimensiones no físicas','Describe ayuda funcional','Asigna seguimiento','Comprueba comprensión']},[
   ['Daniel camina acompañado, pero olvida indicaciones y tiene miedo intenso. ¿Qué debe incluir el alta?','Necesidades físicas y no físicas con seguimiento','Conclusión de recuperación completa por la marcha','Plan de fuerza que omita la dificultad cognitiva','Alta sin cuidador porque completó el pasillo','Control condicionado a perder nuevamente la marcha','Necesidades físicas y no físicas con seguimiento describen mejor la recuperación. La marcha no elimina barreras para autocuidado, comprensión o participación.'],
   ['NICE propone revisión a dos o tres meses para necesidades pos-UCI. ¿Qué implica si hay deterioro una semana después del alta?','Reevaluar antes por el cambio clínico','Esperar al plazo para no alterar el protocolo','Registrar el deterioro sin modificar la cita','Duplicar ejercicio hasta llegar a la revisión','Conservar el plan porque ya se cerró la internación','Reevaluar antes responde al cambio clínico. Un plazo orientativo de seguimiento no es una instrucción para demorar problemas nuevos.'],
   ['¿Qué componente del pase facilita continuidad real de rehabilitación?','Necesidad, responsable y forma de acceso','Diagnóstico principal sin nivel de ayuda actual','Listado de equipos retirados sin plan futuro','Fecha de ingreso sin evolución de actividades','Cantidad de sesiones completadas sin próximos pasos','Necesidad, responsable y forma de acceso permiten que el siguiente equipo actúe. Un documento descriptivo sin continuidad definida puede dejar necesidades sin atención.'],
   ['Un cuidador no entiende cómo ayudar en casa. ¿Qué acción mejora el cierre del plan?','Revisar instrucciones y comprobar su comprensión','Repetir la misma explicación a mayor velocidad','Entregar el alta sin permitir preguntas adicionales','Asumir que aprenderá al observar al paciente','Reemplazar la orientación por una firma de recepción','Revisar instrucciones y comprobar comprensión permite detectar dudas y ajustar apoyos. Una firma o la simple entrega no equivalen a un plan comprendido.']])
];
const ventilationLessons=[
 lesson(vent,1,'Evaluación del paciente conectado al ventilador',['kin-vent'],'Leer soporte, respuesta y seguridad sin reducir la evaluación al equipo.',
  'Evaluar al paciente ventilado incluye observar a la persona, revisar datos fisiológicos, vía aérea, configuración, curvas y humidificación. AARC destaca volumen corriente expresado por peso predicho, presión meseta, PEEP y auto-PEEP como componentes relevantes. No basta con copiar los valores programados: hay que distinguir lo configurado de lo medido y relacionarlo con respuesta clínica.\n\nComo vocabulario inicial, volumen corriente es el volumen por respiración; PEEP es la presión al final de la espiración y FiO₂ la fracción de oxígeno inspirada. La presión pico y la meseta no son intercambiables; su interpretación depende de cómo se obtuvieron y del contexto. Una alarma informa un problema potencial, no su diagnóstico. Ante alarma con deterioro, la prioridad es valorar al paciente y pedir asistencia según el circuito de la unidad.\n\nCaso docente: un alumno registra «presión alta» sin precisar cuál ni cuándo. El pase queda incompleto. Debe describir dato, tendencia, síntomas, soporte y acciones realizadas, sin atribuir una causa que no fue evaluada. La práctica de este módulo consiste en leer registros ficticios y formular preguntas, no modificar un ventilador real. Los cambios de soporte requieren competencia demostrada, indicación y coordinación con el equipo responsable.',
  'Silenciar alarmas o modificar parámetros antes de evaluar al paciente y el problema.',
  'AARC 2024: evaluación centrada en el paciente; este módulo enseña reconocimiento y comunicación, no titulación autónoma.',
  {scenario:'Un monitor ficticio muestra alarma de presión con mayor trabajo respiratorio. Preparar evaluación y pase, sin intervenir sobre equipos reales.',checklist:['Prioriza paciente','Distingue dato programado y medido','Describe tendencia','Solicita respuesta adecuada']},[
   ['Suena una alarma y el paciente presenta mayor trabajo respiratorio. ¿Cuál es la prioridad?','Valorar al paciente y activar asistencia del equipo','Silenciar la alarma y continuar el registro habitual','Elevar límites de alarma para evitar interrupciones','Cambiar parámetros al azar hasta que deje de sonar','Esperar el próximo control porque el equipo funciona','Valorar al paciente y activar asistencia prioriza el deterioro. La alarma no se resuelve sólo silenciándola ni modificando parámetros sin evaluación.'],
   ['¿Qué distinción mejora un pase sobre ventilación mecánica?','La relación del soporte con la respuesta clínica observada','Configuración seleccionada sin respuesta del paciente','Una curva aislada como diagnóstico definitivo del problema','Saturación periférica como único dato del pase ventilatorio','Valores iniciales sin describir los cambios posteriores','La relación del soporte con la respuesta clínica observada describen la relación paciente–ventilador. Copiar la configuración no informa por sí solo qué ocurre con la persona.'],
   ['Un registro dice presión alta sin identificar la medición. ¿Qué aclaración es necesaria?','El tipo de presión y las condiciones en que se obtuvo','Cuánto marcó la alarma sin precisar tipo de presión','Qué PEEP estaba programada sin aclarar la medición alta','Qué saturación tenía sin describir mecánica ni contexto','Qué FiO₂ recibió ayer sin registrar el cambio actual','Qué presión, cómo se midió y contexto son necesarios porque pico y meseta no son intercambiables. Una etiqueta ambigua no permite interpretar el hallazgo.'],
   ['¿Qué dato recomienda AARC para documentar el volumen corriente en relación con el tamaño corporal?','Mililitros por kilogramo de peso predicho','Mililitros por kilogramo del peso actual sin ajuste','Litros por minuto sin frecuencia respiratoria','Porcentaje del peso declarado al ingreso','Volumen absoluto elegido por edad del paciente','Mililitros por kilogramo de peso predicho permite valorar el volumen en relación con tamaño pulmonar estimado. El peso actual, especialmente con obesidad o edema, no es equivalente.']]),
 lesson(vent,2,'Ventilación protectora y posición prona',['kin-ards','kin-vent'],'Reconocer objetivos de protección pulmonar y el trabajo coordinado.',
  'En SDRA, ATS mantiene estrategias que limitan volumen corriente a 4–8 mL/kg de peso predicho y presión meseta por debajo de 30 cmH₂O, además de prono durante más de 12 horas por día en SDRA grave. Estos objetivos se implementan dentro del tratamiento integral y no son una autorización para que un principiante ajuste soporte sin supervisión. El peso predicho se relaciona con talla y sexo de la fórmula, no con peso actual por edema u obesidad.\n\nPara comprender un registro, pedí conocer método y condiciones de medición. No conviertas una cifra aislada en diagnóstico ni supongas que aumentar oxígeno resuelve todo deterioro. La elección de PEEP y otras medidas requiere evaluación especializada. ATS 2024 también recomienda evitar maniobras de reclutamiento prolongadas en SDRA moderado a grave.\n\nEl prono es un procedimiento de equipo. En la preparación docente identificá roles, vía aérea, líneas, ojos, piel y apoyos; la unidad usa su lista y técnica entrenada. Después se revisan dispositivos y respuesta. Caso de cálculo: si el peso predicho ya validado es 60 kg, 6 mL/kg corresponden a 360 mL. Ese cálculo comprueba unidades, pero no determina por sí solo la prescripción. Nunca practiques un giro de paciente ventilado sin entrenamiento y personal suficiente.',
  'Calcular volumen por peso real o convertir un cálculo correcto en una orden terapéutica independiente.',
  'ATS 2024 conserva recomendaciones protectoras previas e incorpora cambios. Los umbrales citados se refieren al SDRA y al contexto de esa guía.',
  {scenario:'Revisar un registro ficticio con peso predicho de 60 kg y un plan de prono. Calcular unidades y preparar lista de coordinación.',checklist:['Usa peso predicho','Calcula con unidades','Distingue cálculo de indicación','Revisa roles y dispositivos']},[
   ['Un ejemplo tiene peso predicho validado de 60 kg. ¿Cuánto corresponde a 6 mL/kg?','360 mL por respiración','600 mL por respiración','240 mL por respiración','420 mL por respiración','720 mL por respiración','360 mL por respiración resulta de multiplicar 60 kg por 6 mL/kg. Verificar el cálculo no sustituye la decisión clínica ni autoriza a programar ese valor.'],
   ['Un paciente con SDRA pesa 110 kg por obesidad; su peso predicho es 65 kg. ¿Qué base se usa para expresar el volumen protector?','El peso predicho de 65 kg','El peso actual de 110 kg','El promedio entre ambos pesos','El peso al ingreso más el balance positivo','El peso elegido según la presión arterial','El peso predicho de 65 kg es la referencia de la estrategia protectora. El peso actual por obesidad o edema no representa el tamaño pulmonar estimado.'],
   ['¿Qué describe mejor el prono en SDRA grave según la recomendación citada?','Intervención prolongada coordinada por equipo entrenado','Cambio postural breve efectuado por una persona sola','Sustituto de la evaluación de ventilación protectora','Procedimiento guiado exclusivamente por comodidad','Actividad que permite omitir la revisión de la vía aérea','Intervención prolongada coordinada requiere planificación y seguridad. ATS recomienda más de 12 horas por día en SDRA grave; el detalle operativo depende del equipo y protocolo.'],
   ['Durante revisión del plan de SDRA moderado a grave se propone reclutamiento prolongado por rutina. ¿Qué indica ATS 2024?','Recomienda evitar maniobras de reclutamiento prolongadas','Las exige antes de cada sesión de rehabilitación','Las considera equivalentes a sentar al paciente','Las indica por cualquier aumento aislado de secreciones','Las utiliza para reemplazar la medición de volumen','ATS recomienda evitar maniobras de reclutamiento prolongadas en ese contexto. Esta recomendación no se confunde con otras decisiones individualizadas de soporte.']]),
 lesson(vent,3,'Ventilación no invasiva: selección y fracaso',['kin-niv','kin-vent'],'Identificar candidatos, vigilar respuesta y reconocer necesidad de escalamiento.',
  'La VNI tiene evidencia relevante en indicaciones específicas, como exacerbación de EPOC con acidosis respiratoria. No toda disnea ni toda hipoxemia comparten esa indicación. La guía ERS/ATS contempla VNI bilevel en EPOC con pH de 7,35 o menos por acidosis respiratoria, integrando clínica y evaluación médica. Un pH menor se asocia a mayor riesgo de fracaso y exige vigilancia y capacidad de intubación si se necesita.\n\nAntes de iniciar, el equipo valora cooperación, protección de vía aérea, secreciones, riesgo de aspiración, estado circulatorio y recursos. La respuesta incluye trabajo respiratorio, frecuencia, confort, estado mental y gasometría según el plan. La mejora de saturación no demuestra por sí sola resolución de falla ventilatoria. Empeoramiento o falta de respuesta requieren reevaluación oportuna; no se debe demorar el soporte indicado para insistir indefinidamente con la máscara.\n\nEl ajuste de interfaz debe atender fugas, tolerancia y piel. Una fuga no se corrige automáticamente apretando al máximo. Caso docente: una persona se vuelve somnolienta y respira peor pese a SpO₂ conservada. El pase debe comunicar el cambio, el tiempo de evolución y la respuesta al tratamiento, solicitando reevaluación urgente. Este módulo no define presiones iniciales ni reemplaza entrenamiento práctico de VNI.',
  'Interpretar una mejor SpO₂ como éxito suficiente y retrasar el escalamiento ante deterioro.',
  'ERS/ATS 2017: indicación específica y vigilancia. Evaluación de interfaz complementada por AARC; no es un protocolo universal de inicio.',
  {scenario:'Paciente con EPOC en VNI empeora en conciencia y trabajo respiratorio. Identificar los datos para el pase y la urgencia de reevaluar.',checklist:['Reconoce deterioro','No se guía sólo por SpO₂','Considera vía aérea y respuesta','Solicita escalamiento oportuno']},[
   ['¿Qué escenario coincide con una indicación respaldada de VNI bilevel en ERS/ATS?','EPOC exacerbada con acidosis respiratoria evaluada','Disnea por cualquier causa sin evaluación del cuadro','Hipoxemia aislada que define por sí sola la modalidad','Somnolencia progresiva sin valorar protección de vía aérea','Necesidad inmediata de intubación que se decide aplazar','EPOC exacerbada con acidosis respiratoria es una indicación respaldada, con selección y vigilancia. No se extrapola a toda disnea ni justifica retrasar una intubación necesaria.'],
   ['Con VNI, mejora SpO₂ pero empeoran somnolencia y trabajo respiratorio. ¿Cómo interpretás la respuesta?','Deterioro que requiere reevaluación y posible escalamiento','Éxito demostrado porque mejoró la oxigenación periférica','Adaptación esperable que permite espaciar los controles','Respuesta favorable que autoriza retirar supervisión','Necesidad de aumentar actividad para mantener vigilia','Deterioro que requiere reevaluación integra conciencia y trabajo respiratorio. La SpO₂ mejorada no excluye hipercapnia ni fracaso del soporte.'],
   ['Una interfaz produce fuga y lesión en el puente nasal. ¿Qué revisión corresponde?','Ajuste, tamaño, piel y tolerancia de la interfaz','Apretar las correas hasta eliminar toda fuga visible','Cubrir la lesión sin revisar presión ni posición','Omitir la revisión si el ventilador no activa alarmas','Cambiar la meta de saturación para compensar la fuga','Ajuste, tamaño, piel y tolerancia deben revisarse en conjunto. Apretar más sin evaluación puede agravar lesión y no resolver la causa de la fuga.'],
   ['¿Qué recurso es esencial cuando se prueba VNI en una situación con riesgo elevado de fracaso?','Vigilancia y capacidad de escalamiento oportuno','Disponibilidad de una máscara adicional sin supervisión','Una saturación inicial dentro del objetivo individual','Un formulario firmado que reemplace la reevaluación','Una duración fija sin importar la evolución clínica','Vigilancia y capacidad de escalamiento permiten responder ante fracaso. La selección inicial o una firma no reemplazan la reevaluación del tratamiento.']]),
 lesson(vent,4,'Vía aérea artificial y aspiración segura',['kin-suction'],'Reconocer indicación y medidas para reducir daño durante aspiración.',
  'La aspiración de vía aérea artificial se basa en una evaluación: secreciones visibles, ruidos y cambios compatibles pueden orientar su necesidad. No es una maniobra para ejecutar por costumbre ni como respuesta automática a toda alarma. AARC 2022 recomienda preoxigenación en adultos y pediatría, evitar generalmente instilar solución salina, técnica estéril cuando el sistema es abierto y limitar cada procedimiento de aspiración a un máximo de 15 segundos.\n\nSe usa aspiración superficial antes de considerar profunda cuando la primera es inefectiva. La técnica, tamaño del catéter y presión deben ajustarse al tubo, población y protocolo; este curso no reemplaza su entrenamiento supervisado. Antes y después se evalúa tolerancia, vía aérea y resultado. Sangrado, desaturación u otros cambios requieren interrumpir y reevaluar según la situación. No se prolonga una maniobra simplemente porque todavía hay secreciones.\n\nEjercicio docente: preparar una hoja de decisión con motivo, riesgos, preparación y resultado esperado. Si el problema persiste, volver a evaluar si la causa realmente es secreción, sin encadenar aspiraciones hasta obtener un número deseado. Separá en el registro lo observado de lo inferido. En una simulación de aula se utiliza material de entrenamiento, sin introducir sondas ni ensayar aspiración sobre compañeros. El objetivo es explicar una decisión segura y sus límites.',
  'Instilar suero o prolongar aspiración de rutina sin reevaluar indicación y tolerancia.',
  'AARC 2022 combina revisión de evidencia y consenso. Los límites son máximos de seguridad, no metas obligatorias de duración.',
  {scenario:'Preparar aspiración simulada de una vía aérea artificial con secreciones visibles; aparece intolerancia. Explicar preparación, interrupción y registro.',checklist:['Justifica indicación','Evita salina rutinaria','Describe preparación y técnica','Reevalúa tolerancia y resultado']},[
   ['Antes de aspirar una vía aérea artificial, ¿qué pregunta organiza mejor la decisión?','Qué hallazgos indican necesidad en este momento','Cuánto tiempo pasó desde la última firma de turno','Qué cantidad fija de aspiraciones resta en la agenda','Qué número de catéteres debe utilizarse por guardia','Cuántas alarmas hubo sin observar al paciente','Qué hallazgos indican necesidad centra la maniobra en evaluación clínica. El horario o número de alarmas no establecen por sí solos que haya secreciones a remover.'],
   ['Un colega propone instilar solución salina antes de toda aspiración. ¿Qué expresa AARC 2022?','Evitar en general la instilación rutinaria de salina','Utilizarla como requisito antes de cualquier aspiración','Reemplazar con ella la preoxigenación indicada','Usarla para confirmar por sí sola permeabilidad del tubo','Mantenerla aunque produzca deterioro durante la maniobra','Evitar en general la instilación rutinaria de salina es la recomendación citada. Su uso no reemplaza preparación, evaluación ni técnica adecuada.'],
   ['¿Cómo interpretás el máximo de 15 segundos por procedimiento de aspiración?','Es un límite y puede requerirse interrumpir antes','Es el mínimo necesario para que la técnica sea válida','Es una meta que debe completarse ante desaturación','Es el tiempo de espera antes de valorar al paciente','Es una autorización para repetir sin reevaluar respuesta','Es un límite, no una duración obligatoria. La intolerancia exige interrumpir antes y reevaluar; no habilita repeticiones sucesivas sin revisar la necesidad.'],
   ['La aspiración superficial fue eficaz. ¿Qué justifica pasar a aspiración profunda inmediatamente?','No hay indicación de profundizar si ya fue eficaz','Completar la secuencia de rutina aunque no haga falta','Obtener una muestra mayor por costumbre del turno','Confirmar eficacia repitiendo con más profundidad','Prevenir toda alarma futura mediante una maniobra extra','No hay indicación de profundizar si ya fue eficaz. AARC reserva la aspiración profunda para cuando la superficial no resulta efectiva, reduciendo intervenciones innecesarias.']]),
 lesson(vent,5,'Prueba de respiración espontánea y extubación',['kin-sbt'],'Distinguir preparación, tolerancia de prueba y evaluación de extubación.',
  'Liberación del ventilador y extubación son decisiones relacionadas pero distintas. Una prueba de respiración espontánea (PRE) evalúa capacidad para respirar con soporte reducido o sin él según protocolo; retirar el tubo también exige valorar protección de vía aérea, tos, secreciones y otros riesgos. Aprobar la prueba no ordena automáticamente extubar.\n\nAARC 2024 sugiere que el índice de respiración rápida superficial no es necesario para decidir preparación para PRE; la prueba puede realizarse con o sin presión de soporte y se recomienda un abordaje estandarizado diario. También sugiere no aumentar FiO₂ durante la prueba. Estas recomendaciones son condicionales, con distinta certeza; no eliminan valoración de causa de insuficiencia, oxigenación, circulación y capacidad de iniciar esfuerzo.\n\nDurante la prueba se observan patrón respiratorio, intercambio gaseoso, estado circulatorio y confort. Si se desarrolla deterioro, se informa y se termina o ajusta la conducta según el protocolo, restituyendo el soporte necesario; no se oculta una falla aumentando oxígeno para poder anotar «aprobada». Caso docente: un paciente tolera la PRE pero mantiene tos débil y abundantes secreciones. El pase debe separar el resultado de la prueba de los problemas para proteger la vía aérea. La decisión final pertenece al equipo competente y no al resultado del examen de este curso.',
  'Equiparar PRE tolerada con extubación segura o modificar condiciones para hacer que la prueba parezca exitosa.',
  'AARC 2024: recomendaciones condicionales. La evaluación clínica y las condiciones del protocolo siguen siendo necesarias.',
  {scenario:'Paciente tolera PRE pero presenta tos débil y secreciones abundantes. Preparar el pase sin anticipar una orden de extubación.',checklist:['Distingue PRE de extubación','Describe tos y secreciones','Reconoce condiciones de la prueba','Solicita decisión del equipo']},[
   ['Un paciente tolera PRE, pero tiene tos débil y secreciones abundantes. ¿Qué conclusión corresponde?','Requiere valorar seguridad de extubación además de la PRE','Puede extubarse porque la PRE resuelve toda la evaluación','Debe reiniciar ventilación invasiva por un plazo fijo','La tos deja de importar tras tolerar el esfuerzo','Las secreciones se evalúan después de retirar el tubo','Requiere valorar seguridad de extubación porque proteger la vía aérea y manejar secreciones son problemas adicionales. Tolerar PRE no decide por sí solo retirar el tubo.'],
   ['¿Qué indica AARC 2024 sobre el índice de respiración rápida superficial para decidir preparación para PRE?','No es necesario como requisito para decidir la prueba','Es obligatorio antes de cualquier evaluación diaria','Sustituye la evaluación hemodinámica y de oxigenación','Define por sí solo si corresponde retirar el tubo','Debe calcularse para aumentar FiO₂ durante la prueba','No es necesario como requisito según la recomendación condicional. La decisión sigue incluyendo reversión de la causa, oxigenación, estabilidad y esfuerzo inspiratorio.'],
   ['Durante una PRE aparece intolerancia y se propone subir FiO₂ para anotarla como aprobada. ¿Qué corresponde?','Evaluar intolerancia y restituir soporte según protocolo','Aumentar FiO₂ y conservar la etiqueta de prueba exitosa','Continuar hasta el plazo previsto sin revisar síntomas','Interpretar el cambio como éxito si mejora la saturación','Omitir el ajuste del registro para mantener comparabilidad','Evaluar intolerancia y restituir soporte prioriza seguridad. AARC sugiere no aumentar FiO₂ durante PRE; tratar deterioro no debe ocultarse ni registrarse como éxito sin contexto.'],
   ['Según AARC 2024, ¿qué modalidad puede usarse para una PRE?','Con o sin presión de soporte según el protocolo','Presión de soporte como única modalidad permitida','Ausencia de soporte como única opción aceptable','Aumento progresivo de FiO₂ como criterio de modalidad','Ventilación totalmente controlada sin esfuerzo espontáneo','Con o sin presión de soporte son opciones contempladas en la recomendación condicional. La modalidad se implementa con evaluación y protocolo, sin confundirla con ventilación controlada.']])
];

function course(id,title,summary,prerequisites,lessons){
 return {id,title,summary,category:'kinesiologia',professionalCategory:'kinesiologos',pathway:'personal-sanitario',audience:'Kinesiólogos y estudiantes avanzados bajo supervisión',subtitle:'Kinesiología · adultos · nivel introductorio',prerequisites,language:'es',evidenceChecked:checked,examMinutes:40,
  scope:'Formación continua independiente para adultos. No equivale a título, certificación oficial ni habilitación para procedimientos. Aplicación clínica según incumbencias, capacitación presencial y protocolos locales.',
  reviewStatus:'Bibliografía contrastada el 29/10/2026; revisión docente especializada pendiente.',
  completion:'Leer los cinco módulos y aprobar la evaluación integral con al menos 80% (16/20). Casos y simulaciones para practicar razonamiento; no acreditan destreza presencial.',
  studyMinutes:165,studyTimeNote:'Estimación orientativa: 125 min de estudio y actividades + 40 min de evaluación; no son horas acreditadas.',
  outcomes:lessons.map(l=>l.objective),references:[...new Set(lessons.flatMap(l=>l.references))],lessons};
}
