const questionSourceOverrides={
 'kine-clinica-m1-q4':'kin-whodas',
 'kine-clinica-m3-q2':'kin-ng59','kine-clinica-m3-q3':'kin-ng59',
 'kine-respiratoria-m1-q4':'kin-oxygen',
 'kine-respiratoria-m3-q1':'kin-bts','kine-respiratoria-m3-q4':'kin-bts',
 'kine-respiratoria-m4-q3':'kin-pr','kine-respiratoria-m4-q4':'kin-pr',
 'kine-uci-m4-q2':'kin-team',
 'kine-ventilacion-m3-q3':'kin-vent'
};
for(const c of kinesiologyCourses)for(const l of c.lessons)for(const q of l.questions){
 q.source=questionSourceOverrides[q.id]||q.source;
 q.references=[q.source,...l.references.filter(id=>id!==q.source)];
}

function scenario(courseId,title,summary,source,lessonId,rows){
 const id=`${courseId}-caso`;
 return {id,courseId,title,summary,source,lessonId,steps:rows.map((row,i)=>{
  const q=question(`${id}-s${i+1}`,source,title,i,row);
  return {...q,text:q.prompt,next:i===rows.length-1?null:i+1,wrong:i};
 })};
}
